import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Unavailable integrations and payment uncertainty","description":"","frontmatter":{},"headers":[],"relativePath":"help/integration-problems.md","filePath":"help/integration-problems.md"}'),r={name:"help/integration-problems.md"};function o(s,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="unavailable-integrations-and-payment-uncertainty" tabindex="-1">Unavailable integrations and payment uncertainty <a class="header-anchor" href="#unavailable-integrations-and-payment-uncertainty" aria-label="Permalink to &quot;Unavailable integrations and payment uncertainty&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Source-reviewed training draft · TransferBook+ v0.7.9. Verify installed release, permissions and configuration. Use authorized synthetic training data; no live activation is implied.</p></div><h2 id="why-is-an-integration-not-configured" tabindex="-1">Why is an integration not configured? <a class="header-anchor" href="#why-is-an-integration-not-configured" aria-label="Permalink to &quot;Why is an integration not configured?&quot;">​</a></h2><p>An adapter in the catalogue does not establish a live connection. Approved provider access, configuration and activation may still be required. A sandbox preview does not transmit a real booking.</p><h2 id="can-a-simulated-message-or-gps-point-be-treated-as-live" tabindex="-1">Can a simulated message or GPS point be treated as live? <a class="header-anchor" href="#can-a-simulated-message-or-gps-point-be-treated-as-live" aria-label="Permalink to &quot;Can a simulated message or GPS point be treated as live?&quot;">​</a></h2><p>No. Messaging requires appropriate consent and approved provider activation. Simulated fleet coordinates do not establish vehicle location. Pending consent is not affirmative consent.</p><h2 id="what-if-a-payment-is-uncertain" tabindex="-1">What if a payment is uncertain? <a class="header-anchor" href="#what-if-a-payment-is-uncertain" aria-label="Permalink to &quot;What if a payment is uncertain?&quot;">​</a></h2><p>Inspect the existing ledger and supported reconciliation or recovery controls. Do not issue another charge just because a response is missing. Escalate with the sanitized provider and reservation references. Never include card details or credentials.</p><h2 id="where-to-get-help" tabindex="-1">Where to get help <a class="header-anchor" href="#where-to-get-help" aria-label="Permalink to &quot;Where to get help&quot;">​</a></h2><p>Check the integration&#39;s readiness and authorization with the responsible administrator. Disabled controls must remain disabled until separately approved.</p><p>See <a href="/integrations/activation-and-channels.html">Integration readiness</a>, <a href="/integrations/conversational-booking.html">Conversational booking</a>, <a href="/integrations/live-tracking.html">Live tracking</a> and <a href="/integrations/payment-providers.html">Payment providers</a>.</p>',11)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
